import{_ as a,o,c as e,a2 as r}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 6 章 记忆系统：让 AI 越来越懂你","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 6 章 记忆系统：让 AI 越来越懂你.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 6 章 记忆系统：让 AI 越来越懂你.md"}'),l={name:"bluebook/第一篇 使用手册：先把我用起来/第 6 章 记忆系统：让 AI 越来越懂你.md"};function i(d,t,n,s,u,h){return o(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="第-6-章-记忆系统-让-ai-越来越懂你" tabindex="-1">第 6 章 记忆系统：让 AI 越来越懂你 <a class="header-anchor" href="#第-6-章-记忆系统-让-ai-越来越懂你" aria-label="Permalink to &quot;第 6 章 记忆系统：让 AI 越来越懂你&quot;">​</a></h1><h2 id="_6-1-为什么需要记忆" tabindex="-1">6.1 为什么需要记忆 <a class="header-anchor" href="#_6-1-为什么需要记忆" aria-label="Permalink to &quot;6.1 为什么需要记忆&quot;">​</a></h2><p>每次对话结束，如果我什么都不记得，你就得把项目背景、你的偏好、你的坑，重新讲一遍。这很蠢。</p><p>我有<strong>持久化记忆</strong>：存在你项目对应的 memory 目录里，跨会话保留。下次见面，我还记得你是谁、在做什么、喜欢什么风格。</p><h2 id="_6-2-记忆的四种类型" tabindex="-1">6.2 记忆的四种类型 <a class="header-anchor" href="#_6-2-记忆的四种类型" aria-label="Permalink to &quot;6.2 记忆的四种类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>记什么</th><th>示例</th></tr></thead><tbody><tr><td>user</td><td>关于你这个人</td><td>用户是产品经理，偏好中文简洁文档</td></tr><tr><td>feedback</td><td>你的反馈与偏好</td><td>&quot;不要用被动语态&quot;&quot;先给结论&quot;</td></tr><tr><td>project</td><td>项目背景</td><td>这个项目是 MomaWork 白皮书</td></tr><tr><td>reference</td><td>参考资料</td><td>蓝皮书结构参考、指令模板</td></tr></tbody></table><p>每一条记忆 = 一个 Markdown 文件（带 frontmatter）+ 一条 MEMORY.md 索引。<strong>记忆是透明的文件，你可以随时查看、修改、删除。</strong></p><h2 id="_6-3-记忆是怎么形成的" tabindex="-1">6.3 记忆是怎么形成的 <a class="header-anchor" href="#_6-3-记忆是怎么形成的" aria-label="Permalink to &quot;6.3 记忆是怎么形成的&quot;">​</a></h2><ul><li>你<strong>显式要求</strong>：&quot;记住我偏好 X&quot; → 我立即保存；</li><li>我<strong>主动沉淀</strong>：在合作中发现的稳定偏好（如&quot;用户每次都要 Excel 格式&quot;）；</li><li>你<strong>纠正我</strong>：&quot;我说过不要这样&quot; → 我更新 feedback 记忆。</li></ul><blockquote><p>你可以随时说：&quot;把……忘了&quot; / &quot;记住……&quot;，我都能处理。</p></blockquote><h2 id="_6-4-记忆的正确用法" tabindex="-1">6.4 记忆的正确用法 <a class="header-anchor" href="#_6-4-记忆的正确用法" aria-label="Permalink to &quot;6.4 记忆的正确用法&quot;">​</a></h2><p><strong>要记的：</strong></p><ul><li>稳定的偏好（语言、风格、格式）；</li><li>项目关键决策（为什么这么设计）；</li><li>你的工作上下文（在做什么、下一步是什么）。</li></ul><p><strong>不要记的：</strong></p><ul><li>一次性的临时信息（任务完成就该消失）；</li><li>敏感信息（密码、密钥——记忆文件是明文，请勿存放）；</li><li>会频繁变动的数据（应该放在项目文件里，而不是记忆里）。</li></ul><h2 id="_6-5-记忆与文件的分工" tabindex="-1">6.5 记忆与文件的分工 <a class="header-anchor" href="#_6-5-记忆与文件的分工" aria-label="Permalink to &quot;6.5 记忆与文件的分工&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>记忆    → 关于&quot;怎么做&quot;的稳定知识（偏好、方法、约定）</span></span>
<span class="line"><span>文件    → 关于&quot;做了什么&quot;的具体内容（产物、数据、文档）</span></span></code></pre></div><p>一句话：<strong>文件是仓库，记忆是说明书。</strong></p><h2 id="_6-6-练习" tabindex="-1">6.6 练习 <a class="header-anchor" href="#_6-6-练习" aria-label="Permalink to &quot;6.6 练习&quot;">​</a></h2><ol><li>告诉我 3 条关于你的稳定信息（身份、偏好、常用格式），让我记住。</li><li>让我查看当前的 MEMORY.md 索引，确认记忆已保存。</li><li>故意说错一条，再纠正我，看看 feedback 记忆如何更新。</li></ol><blockquote><p>小结：记忆系统让我从&quot;每次都是陌生人&quot;变成&quot;越用越懂你的老搭档&quot;。你花两分钟喂我的记忆，未来每天都能省两分钟以上的沟通成本。</p></blockquote>`,21)])])}const p=a(l,[["render",i]]);export{c as __pageData,p as default};
